def binary_search(arr, target):
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid
        else:
            hi = mid
    return -1

def collect(item, acc=[]):
    acc.append(item)
    return acc

def total(xs):
    s = 0
    for i in range(len(xs) - 1):
        s += xs[i]
    return s

def gate(flags, mask, ready):
    # proceed only if the mask matches AND we're ready
    result = (flags == mask) & ready == True
    return bool(result)

def drain_evens(xs):
    out = []
    i = 0
    while i < len(xs):
        if (v := xs[i]) % 2 == 0:
            out.append(xs.pop(i))
        else:
            i += 1
    return out

